examples.script:
Set Variable [ $r ; Value: While ( 
[
  // get items in menu 
  items = MBS( "Menu.Items"; $menu ); 
  index = 1;
  count = MBS( "Menu.NumberOfItems"; $menu )
] ; 

// loop till last item
index ≤ count ; 

[ 
  // get the current item
  item = GetValue(items; index);
  // change font size
  r = MBS( "MenuItem.SetFontSize"; item; 16 ); 
  // and continue with next item
  index = index + 1
] ; 0 ) ]

Set Variable [ $r ; Value: Let ( 
/*
MBS-OCR ( language; Image)

Requires tessdata resources [MIT ©]
language: deu ('deu.traineddata), fra, eng, etc.
Image: Container Fieldname ('MyTable::MyField') in Quotes
path: FM/Extensions - put 'tessdata' Folder into FM Extensions Folder

Benjamin Fehr, EfficientBizz GmbH
http://www.efficientbizz.com 
*/

[

// init OCR
	$path = MBS ("Path.FileMakerPathToNativePath"; Get(FileMakerPath)& "Extensions/") ;
	initialize = MBS( "OCR.Initialize"; $path; language) ; 	$Error = initialize ;	
	SegMode = MBS( "OCR.SetPageSegMode"; "Auto");

// Process Image
	$img = MBS("GMImage.NewFromContainer"; Image);
	set =  MBS("OCR.SetImage"; $img) ;
	$result = MBS("OCR.GetText") ;


// Cleanup
	$clean = MBS( "OCR.Cleanup") ; 
	$destroy = MBS( "GMImage.Release"; $img) 


] 
; "" ) ]

Set Variable [ $r ; Value: MBS( "OCR.Load"; "liblept.so.5" ) & 
MBS( "OCR.Load"; "libtesseract.so.5" )

// please install tesseract library, so plugin can load it:
// sudo apt-get install libtesseract5 ]

Set Variable [ $r ; Value: MBS("OCR.Load"; "/Users/cs/Tesseract/tesseract4/tesseract.dylib")

// for macOS, please download from our website 
// https://www.monkeybreadsoftware.com/filemaker/files/Libs/
// which includes leptonica library! ]

Set Variable [ $r ; Value: MBS( "OCR.Load"; "/opt/homebrew/lib/liblept.5.dylib" ) & 
MBS( "OCR.Load"; "/opt/homebrew/lib/libtesseract.4.dylib" )

// install via homebrew
// brew install tesseract-lang ]

Set Variable [ $r ; Value: MBS("Process.SetCurrentDirectory"; "C:\Program Files\Tesseract-OCR") & 
MBS( "OCR.Load"; "liblept-5.dll" ) & 
MBS( "OCR.Load"; "libtesseract-4.dll" )

// get Windows DLL somewhere
// e.g. https://digi.bib.uni-mannheim.de/tesseract/ ]

Set Variable [ $r ; Value: Let ( [
r = MBS( "RunTask.NewTask" );
r = MBS( "RunTask.SetLaunchPath"; "/bin/sh" );
r = MBS( "RunTask.SetArguments"; "-c"; "date;sleep 5;date" );
r = MBS( "RunTask.Launch");
r = MBS( "RunTask.Wait"; "30");
output = MBS( "RunTask.ReadOutputText"; "utf8")
]
; output ) ]
